import { words, groupBy } from 'es-toolkit';
import { isEmpty } from 'es-toolkit/compat';

export interface Row {
  id: number;
  name: string;
  age: number;
}

export type Config = Record<string, unknown>;

export function tokens(text: string): string[] {
  return words(text);
}

export function byAge(rows: Row[]): Record<string, Row[]> {
  return groupBy(rows, (r) => r.age);
}

export function isBlank(value: unknown): boolean {
  return isEmpty(value);
}
EOF
cat > out/t.mjs <<'EOF'
import { words as w1 } from 'lodash';
import { words } from 'es-toolkit';
const c='aB1 -_.Zz9X';let bad=0;
for(let i=0;i<200000;i++){let s='';const n=Math.random()*14|0;for(let j=0;j<n;j++)s+=c[Math.random()*c.length|0];
if(JSON.stringify(w1(s))!==JSON.stringify(words(s))){if(bad++<5)console.log(JSON.stringify(s),w1(s),words(s));}}
console.log('bad',bad);
EOF
cp out/t.mjs ./t.mjs && node t.mjs; rm t.mjs out/t.mjs; npm run size -- src/module.ts; npm run size -- out/module.ts; npx tsc --noEmit -p . 2>&1 | head

